set -u
L=/scratch/jjyeung/orch_n30/b04_e2ehook_sl; cd $L
echo  | base64 -d | tar xf -; sha256sum sl_tables.py selector_inputs.py name_emb.py
export PYTHONDONTWRITEBYTECODE=1
timeout 600 nice -n 10 /scratch/jjyeung/envs/p1cpu/bin/python -B sl_tables.py --out $L/test2 --scales SCALES_S4.json --only arkitscenes/41048124,scannet/scene0150_01 --procs 2 > test2.log 2>&1
cat test2.log | cut -c1-2500
n=$(grep -c '"rows"' test2.log)
if [ "$n" = 2 ]; then
  tmux new-session -d -s sl_tab "cd $L && PYTHONDONTWRITEBYTECODE=1 nice -n 10 /scratch/jjyeung/envs/p1cpu/bin/python -B sl_tables.py --out $L/full --scales SCALES_S4.json --procs 8 > full.log 2>&1"
  echo LAUNCHED_FULL
fi
mkdir -p $L/emb
tmux new-session -d -s sl_emb "cd $L && PYTHONDONTWRITEBYTECODE=1 XDG_CACHE_HOME=$L/emb/cache HF_HOME=$L/emb/cache/hf nice -n 10 /scratch/jjyeung/envs/sam3_capretry_native_v1/bin/python -B name_emb.py $L/emb > emb.log 2>&1"
echo LAUNCHED_EMB; tmux ls
